// Content with portions generated by generative AI platform

package org.eclipse.kura.util.zip;

import static org.eclipse.kura.util.zip.TestZipArchives.FILE_CONTENT;
import static org.eclipse.kura.util.zip.TestZipArchives.FILE_NAME;
import static org.eclipse.kura.util.zip.TestZipArchives.MAX_ALLOWED_ENTRIES;
import static org.eclipse.kura.util.zip.TestZipArchives.MAX_ALLOWED_UNCOMPRESSED_SIZE;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.io.File;
import java.io.IOException;

import org.apache.commons.io.FileUtils;
import org.junit.After;
import org.junit.Test;

public class UnZipTest {

    private static final String WORK_FOLDER = "/tmp/kura_test/";
    private static final String INPUT_ZIP_FILE = WORK_FOLDER + "input.zip";
    private static final String UNCOMPRESSED_INPUT_FILE = "uncompressedFile.txt";
    private static final String INPUT_TAR_FILE = "singleCompressedFile.tar";
    private static final String TEST_CLASSES_FOLDER = "target/test-classes/";

    private byte[] compressedInput;
    private boolean exceptionCaught;

    @After
    public void clean() throws IOException {
        FileUtils.deleteDirectory(new File(WORK_FOLDER));
    }

    @Test
    public void unZipFileTest() throws IOException {
        givenCompressedFile();

        whenFileIsUnzipped();

        thenUncompressedFileExists();
        thenUncompressedFileIsAFile();
        thenUncompressedFileIsCorrect();
    }

    @Test
    public void unZipByteStreamTest() throws IOException {
        givenCompressedStream();

        whenStreamIsUnzipped();

        thenUncompressedFileExists();
        thenUncompressedFileIsAFile();
        thenUncompressedFileIsCorrect();
    }

    @Test
    public void catchExceptionWhenTooManyFilesTest() throws IOException {
        givenArchiveWithEntryCount(MAX_ALLOWED_ENTRIES + 1);

        whenFileIsUnzippedCatchingIllegalState();

        thenExceptionIsCaught();
    }

    @Test
    public void catchExceptionWhenTooBigFileTest() throws IOException {
        givenArchiveWithUncompressedSize(MAX_ALLOWED_UNCOMPRESSED_SIZE + 1024 * 1024);

        whenFileIsUnzippedCatchingIllegalState();

        thenExceptionIsCaught();
    }

    @Test
    public void catchExceptionWhenIllegalPathFileTest() throws IOException {
        givenArchiveWithAnEntryOutsideTheTargetFolder();

        whenFileIsUnzippedCatchingIoError();

        thenExceptionIsCaught();
    }

    @Test
    public void unZipMultipleFilesTest() throws IOException {
        givenArchiveWithMultipleFiles();

        whenFileIsUnzipped();

        thenMultipleUncompressedFileExists();
    }

    @Test
    public void unZipUncompressedFileTest() throws IOException {
        givenUnCompressedFile();

        whenUncompressedFileIsUnzipped();

        thenUncompressedFileNotExist();
    }

    @Test
    public void unZipTarFileTest() throws IOException {
        givenTarCompressedFile();

        whenTarFileIsUnzipped();

        thenUncompressedFileNotExist();
    }

    private void givenCompressedFile() throws IOException {
        TestZipArchives.writeTo(TestZipArchives.withSingleFile(), INPUT_ZIP_FILE);
    }

    private void givenCompressedStream() throws IOException {
        createOutputFolder();
        this.compressedInput = TestZipArchives.withSingleFile();
    }

    private void givenArchiveWithEntryCount(int entryCount) throws IOException {
        TestZipArchives.writeTo(TestZipArchives.withEntryCount(entryCount), INPUT_ZIP_FILE);
    }

    private void givenArchiveWithUncompressedSize(long uncompressedSize) throws IOException {
        TestZipArchives.writeTo(TestZipArchives.withUncompressedSize(uncompressedSize), INPUT_ZIP_FILE);
    }

    private void givenArchiveWithAnEntryOutsideTheTargetFolder() throws IOException {
        TestZipArchives.writeTo(TestZipArchives.withEntryOutsideTargetFolder(), INPUT_ZIP_FILE);
    }

    private void givenArchiveWithMultipleFiles() throws IOException {
        TestZipArchives.writeTo(TestZipArchives.withMultipleFiles(), INPUT_ZIP_FILE);
    }

    private void givenUnCompressedFile() throws IOException {
        copyResource(UNCOMPRESSED_INPUT_FILE);
    }

    private void givenTarCompressedFile() throws IOException {
        copyResource(INPUT_TAR_FILE);
    }

    private void createOutputFolder() {
        File inputFolder = new File(WORK_FOLDER);
        inputFolder.mkdirs();
    }

    private void copyResource(String resourceName) throws IOException {
        FileUtils.copyFile(new File(TEST_CLASSES_FOLDER + resourceName), new File(WORK_FOLDER + resourceName));
    }

    private void whenFileIsUnzipped() throws IOException {
        UnZip.unZipFile(INPUT_ZIP_FILE, WORK_FOLDER);
    }

    private void whenStreamIsUnzipped() throws IOException {
        UnZip.unZipBytes(this.compressedInput, WORK_FOLDER);
    }

    private void whenFileIsUnzippedCatchingIllegalState() throws IOException {
        this.exceptionCaught = false;
        try {
            UnZip.unZipFile(INPUT_ZIP_FILE, WORK_FOLDER);
        } catch (IllegalStateException e) {
            this.exceptionCaught = true;
        }
    }

    private void whenFileIsUnzippedCatchingIoError() {
        this.exceptionCaught = false;
        try {
            UnZip.unZipFile(INPUT_ZIP_FILE, WORK_FOLDER);
        } catch (IOException e) {
            this.exceptionCaught = true;
        }
    }

    private void whenUncompressedFileIsUnzipped() throws IOException {
        UnZip.unZipFile(WORK_FOLDER + UNCOMPRESSED_INPUT_FILE, WORK_FOLDER);
    }

    private void whenTarFileIsUnzipped() throws IOException {
        UnZip.unZipFile(WORK_FOLDER + INPUT_TAR_FILE, WORK_FOLDER);
    }

    private void thenUncompressedFileExists() {
        File uncompressedFile = new File(WORK_FOLDER + FILE_NAME);
        assertTrue(uncompressedFile.exists());
    }

    private void thenUncompressedFileIsAFile() {
        File uncompressedFile = new File(WORK_FOLDER + FILE_NAME);
        assertTrue(!uncompressedFile.isDirectory());
        assertTrue(uncompressedFile.isFile());
    }

    private void thenMultipleUncompressedFileExists() {
        File uncompressedFile = new File(WORK_FOLDER + FILE_NAME);
        File uncompressedFile1 = new File(WORK_FOLDER + "file1.txt");
        assertTrue(uncompressedFile.exists());
        assertTrue(uncompressedFile1.exists());
    }

    private void thenUncompressedFileIsCorrect() throws IOException {
        File file = new File(WORK_FOLDER + FILE_NAME);
        String content = FileUtils.readFileToString(file, "UTF-8");
        assertEquals(FILE_CONTENT, content);
    }

    private void thenExceptionIsCaught() {
        assertTrue(this.exceptionCaught);
    }

    private void thenUncompressedFileNotExist() {
        File uncompressedFile = new File(WORK_FOLDER + FILE_NAME);
        assertFalse(uncompressedFile.exists());
    }
}
